function km(times, events){ var n=times.length; var idx=[]; for(var i=0;i<n;i++) idx.push(i);
  idx.sort(function(a,b){return times[a]-times[b];});
  var S=1; var out=[{t:0,S:1}]; var atRisk=n; var i=0;
  while(i<n){ var j=i; while(j+1<n && times[idx[j+1]]===times[idx[i]]) j++;
    var d=0; for(var k=i;k<=j;k++){ if(events[idx[k]]===1) d++; }
    S = S * (atRisk - d)/atRisk; out.push({t:times[idx[i]], S:S}); atRisk -= (j-i+1); i=j+1; }
  return out; }
var EXPORTS={km:km};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
